// What to emit. Step 0: a program is one integer, and the output is C that
// prints it. Later steps emit assembly through a target interface; C is
// the quickest way to a binary on any machine and is enough to start.
import { CompileError } from './errors.ts';
import type { Form } from './sexp.ts';

const INT_MIN = -(2n ** 62n);
const INT_MAX = 2n ** 62n - 1n;

const compileExpr = (f: Form): string => {
    if (f.kind !== 'int') throw new CompileError(`can't compile ${f.kind} yet`, f.pos.line, f.pos.col);
    if (f.value < INT_MIN || f.value > INT_MAX) throw new CompileError('integer out of range', f.pos.line, f.pos.col);
    return `rt_int(${f.value}LL)`;
};

export const compileProgram = (forms: readonly Form[]): string => {
    if (forms.length !== 1) throw new CompileError('a program is one form', forms[0]?.pos.line ?? 1, forms[0]?.pos.col ?? 1);
    return [
        '#include "rt.h"',
        'rt_value lang_main(void) {',
        `    return ${compileExpr(forms[0])};`,
        '}',
        '',
    ].join('\n');
};

// Shared between the runtime and generated code. Every name is prefixed
// rt_/RT_: macOS's <stdlib.h> pulls in <sys/wait.h>, which has a P_PID,
// and its <sys/types.h> defines major() and minor() as macros.
#ifndef RT_H
#define RT_H
#include <stdint.h>

// Step 0's value: a 63-bit integer, shifted left one bit, tag 0. Later
// steps add tags for the other immediates and for pointers.
typedef intptr_t rt_value;
#define RT_INT_TAG 0
#define RT_INT_SHIFT 1

// Multiplied, not shifted: a left shift of a negative value is undefined
// before C23, and UBSan says so; the compiler emits the shift anyway.
static inline rt_value rt_int(int64_t n) { return (rt_value)(n * (1 << RT_INT_SHIFT)) | RT_INT_TAG; }

rt_value lang_main(void);
void rt_print(rt_value v);
void rt_fault(const char *what) __attribute__((noreturn));
#endif

// The core: printing, faults, main. The runtime prints the program's
// value, then a newline, and exits 0; a fault goes to stderr and exits 1.
#include <stdio.h>
#include <stdlib.h>
#include "rt.h"

void rt_print(rt_value v) {
    if ((v & 1) == RT_INT_TAG) printf("%lld", (long long)(v >> RT_INT_SHIFT));
    else rt_fault("unknown value");
}

void rt_fault(const char *what) {
    fflush(stdout);
    fprintf(stderr, "fault: %s\n", what);
    exit(1);
}

int main(void) {
    rt_print(lang_main());
    putchar('\n');
    return 0;
}

// The data the compiler works on. Every form carries where it came from.
export type Pos = { line: number; col: number };
export type Form =
    | { kind: 'int'; value: bigint; pos: Pos }
    | { kind: 'symbol'; name: string; pos: Pos }
    | { kind: 'list'; items: readonly Form[]; pos: Pos };

export const show = (f: Form): string =>
    f.kind === 'int' ? String(f.value)
    : f.kind === 'symbol' ? f.name
    : '(' + f.items.map(show).join(' ') + ')';

// Text to forms: integers, symbols and lists, `;` to the end of a line a
// comment. Character tests rather than regexes, since the language this
// becomes won't have them.
import { CompileError } from './errors.ts';
import type { Form, Pos } from './sexp.ts';

type State = { src: string; i: number; line: number; col: number };

const isSpace = (c: string) => c === ' ' || c === '\n' || c === '\t' || c === '\r';
const isDigit = (c: string) => c >= '0' && c <= '9';
const isDelim = (c: string) => c === '' || isSpace(c) || c === '(' || c === ')' || c === ';';

const at = (s: State): string => s.src[s.i] ?? '';
const pos = (s: State): Pos => ({ line: s.line, col: s.col });
const step = (s: State): State =>
    at(s) === '\n' ? { ...s, i: s.i + 1, line: s.line + 1, col: 1 } : { ...s, i: s.i + 1, col: s.col + 1 };

const skip = (s: State): State => {
    while (true) {
        if (isSpace(at(s))) s = step(s);
        else if (at(s) === ';') { while (at(s) !== '' && at(s) !== '\n') s = step(s); }
        else return s;
    }
};

const readAtom = (s: State): [Form, State] => {
    const p = pos(s);
    let text = '';
    while (!isDelim(at(s))) { text += at(s); s = step(s); }
    const digits = text[0] === '-' ? text.slice(1) : text;
    const isInt = digits.length > 0 && [...digits].every(isDigit);
    return [isInt ? { kind: 'int', value: BigInt(text), pos: p } : { kind: 'symbol', name: text, pos: p }, s];
};

const readForm = (s: State): [Form, State] => {
    s = skip(s);
    const c = at(s);
    if (c === '') throw new CompileError('unexpected end of input', s.line, s.col);
    if (c === ')') throw new CompileError("unexpected ')'", s.line, s.col);
    if (c !== '(') return readAtom(s);
    const p = pos(s);
    const items: Form[] = [];
    s = step(s);
    while (true) {
        s = skip(s);
        if (at(s) === '') throw new CompileError("missing ')'", p.line, p.col);
        if (at(s) === ')') return [{ kind: 'list', items, pos: p }, step(s)];
        const [item, next] = readForm(s);
        items.push(item);
        s = next;
    }
};

// Every top-level form in the text, in order.
export const read = (src: string): Form[] => {
    const forms: Form[] = [];
    let s: State = { src, i: 0, line: 1, col: 1 };
    while (true) {
        s = skip(s);
        if (at(s) === '') return forms;
        const [form, next] = readForm(s);
        forms.push(form);
        s = next;
    }
};

// The one class in the compiler: it plays the part of `raise`. Everything
// else is functions over immutable data, so it can be ported to the
// language itself line by line.
export class CompileError extends Error {
    readonly line: number;
    readonly col: number;
    constructor(message: string, line: number, col: number) {
        super(message);
        this.line = line;
        this.col = col;
    }
}

#!/usr/bin/env python3
"""The mechanical checks: what the working rules say, enforced rather
than remembered. `make checks` runs them all; `make models` regenerates
what the models write.

  models    Every command in a model's docstring (a line that starts
            `python3 t/models/`, with `> file`) is run, and its output
            must equal the file. A file that was patched by hand, or a
            model that was changed without rerunning it, fails here.
            `--write` writes the files instead (make models).
  tests     Every t/*.lang, examples/*.lang and docs/guide/code/*.lang
            has a .expected and the other way round; a test that names a
            model (`t/models/x.py` in its comments) names one that
            exists and that lists the test's files.
  referee   Every referee in t/referee/ (an evaluator of the language
            written from the decisions, not the runtime) is run over
            every golden test, and must print the .expected, or say the
            program is outside what it covers (exit 3), which is skipped.
  commits   Every commit in a range (BASE..HEAD, default origin/main..HEAD)
            that touches compiler/, runtime/ or lib/ names a decision
            (D12) or a plan step (step 3) in its subject, so that the
            change can be found from the log and the log from the
            change. `commit-msg FILE [--staged]` checks one message, for
            the git hook that `make hooks` installs.
"""

import glob
import os
import re
import subprocess
import sys

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
IMPL = ('compiler/', 'runtime/', 'lib/', 'bin/')
TEST_DIRS = ['t', 'examples', 'docs/guide/code']
EXT = '.lang'

def model_commands():
    """(model, args, path) for every regenerating command in every model."""
    out = []
    for model in sorted(glob.glob('t/models/*.py')):
        src = open(model).read()
        for line in src.splitlines():
            m = re.match(r'\s*python3 (t/models/\S+\.py)((?: \S+)*) > (\S+)$', line)
            if m:
                if m.group(1) != model:
                    out.append((model, None, f'{model} lists a command for {m.group(1)}'))
                else:
                    out.append((model, m.group(2).split(), m.group(3)))
    return out

def check_models(write=False):
    bad = []
    commands = model_commands()
    for model, args, path in commands:
        if args is None:
            bad.append(path)
            continue
        r = subprocess.run(['python3', '-I', model, *args], capture_output=True)
        if r.returncode != 0:
            bad.append(f'{model} {" ".join(args)}: exit {r.returncode}\n{r.stderr.decode()}')
            continue
        if write:
            open(path, 'wb').write(r.stdout)
        elif not os.path.exists(path):
            bad.append(f'{path}: not written; `make models`')
        elif open(path, 'rb').read() != r.stdout:
            bad.append(f'{path}: differs from what {model} writes; rerun it (`make models`), don\'t patch the file')
    models_without = [m for m in sorted(glob.glob('t/models/*.py')) if not any(c[0] == m for c in commands)]
    bad += [f'{m}: lists no command that writes a file' for m in models_without]
    print(f'models: {len(commands)} files from {len(set(c[0] for c in commands))} models' + (' written' if write else ''))
    return bad

def check_tests():
    bad = []
    listed = {path for _, _, path in model_commands() if path}
    for d in TEST_DIRS:
        for src in sorted(glob.glob(f'{d}/*{EXT}')):
            base = src[:-len(EXT)]
            if not os.path.exists(base + '.expected'):
                bad.append(f'{src}: no .expected')
            text = open(src).read()
            for model in set(re.findall(r't/models/\S+\.py', text)):
                if not os.path.exists(model):
                    bad.append(f'{src}: names {model}, which doesn\'t exist')
                elif src not in listed:
                    bad.append(f'{src}: names {model}, which doesn\'t list it')
        for exp in sorted(glob.glob(f'{d}/*.expected')):
            if not os.path.exists(exp[:-len('.expected')] + EXT):
                bad.append(f'{exp}: no {EXT} file')
    return bad

def check_referee():
    bad, ran, skipped = [], 0, 0
    referees = sorted(glob.glob('t/referee/*.py'))
    for ref in referees:
        for d in TEST_DIRS:
            for src in sorted(glob.glob(f'{d}/*{EXT}')):
                exp = src[:-len(EXT)] + '.expected'
                if not os.path.exists(exp):
                    continue
                r = subprocess.run(['python3', '-I', ref, src], capture_output=True)
                if r.returncode == 3:
                    skipped += 1
                elif r.returncode != 0:
                    bad.append(f'{ref} on {src}: exit {r.returncode}\n{r.stderr.decode()}')
                elif r.stdout != open(exp, 'rb').read():
                    bad.append(f'{ref} on {src}: the referee and the .expected disagree; one of them is wrong, and the decisions say which')
                else:
                    ran += 1
    print(f'referee: {len(referees)} referees, {ran} tests agree, {skipped} outside them')
    return bad

SUBJECT_OK = re.compile(r'\bD\d+\b|\bstep \d+\b', re.I)

def touches_impl(files):
    return any(f.startswith(IMPL) for f in files)

def check_message(subject, files, what):
    if touches_impl(files) and not SUBJECT_OK.search(subject):
        return [f'{what}: changes {", ".join(sorted({f.split("/")[0] for f in files if f.startswith(IMPL)}))}/ '
                f'but its subject names no decision (D12) or plan step (step 3): "{subject}"']
    return []

def check_commits(rng):
    bad = []
    log = subprocess.run(['git', 'log', '--format=%H%x00%s', rng], capture_output=True, text=True, check=True).stdout
    for line in log.splitlines():
        sha, subject = line.split('\0')
        files = subprocess.run(['git', 'show', '--format=', '--name-only', sha], capture_output=True, text=True, check=True).stdout.split()
        bad += check_message(subject, files, sha[:10])
    print(f'commits: {len(log.splitlines())} in {rng}')
    return bad

def check_commit_msg(path, staged):
    subject = next((l for l in open(path).read().splitlines() if l and not l.startswith('#')), '')
    files = subprocess.run(['git', 'diff', '--cached', '--name-only'], capture_output=True, text=True, check=True).stdout.split() if staged else []
    return check_message(subject, files, 'this commit')

def main(argv):
    os.chdir(ROOT)
    what = argv[0] if argv else 'all'
    if what == 'models':
        bad = check_models('--write' in argv)
    elif what == 'tests':
        bad = check_tests()
    elif what == 'referee':
        bad = check_referee()
    elif what == 'commits':
        upstream = subprocess.run(['git', 'rev-parse', '--verify', '-q', 'origin/main'], capture_output=True).returncode == 0
        bad = check_commits(argv[1] if len(argv) > 1 else 'origin/main..HEAD' if upstream else 'HEAD')
    elif what == 'commit-msg':
        bad = check_commit_msg(argv[1], '--staged' in argv)
    elif what == 'all':
        bad = check_models() + check_tests() + check_referee()
    else:
        sys.exit(__doc__)
    for b in bad:
        print(f'FAIL {b}')
    print(f'{what}: {len(bad)} failed')
    sys.exit(1 if bad else 0)

if __name__ == '__main__':
    main(sys.argv[1:])

#!/usr/bin/env node
// The driver: read, compile to C, write it next to the output, link it
// with the runtime. `node bin/langc.ts -o out file.lang`.
// Exit codes: 0 ok, 1 compile error, 2 usage, toolchain or file error.
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { read } from '../compiler/src/reader.ts';
import { compileProgram } from '../compiler/src/codegen.ts';
import { CompileError } from '../compiler/src/errors.ts';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const usage = () => { console.error('usage: langc -o out file.lang'); process.exit(2); };

const args = process.argv.slice(2);
const at = args.indexOf('-o');
if (at < 0 || args.length !== 3) usage();
const out = args[at + 1]!;
const src = args.find((a, i) => i !== at && i !== at + 1)!;
if (out.startsWith('-')) usage();

let text: string;
try { text = readFileSync(src, 'utf8'); }
catch (e) { console.error(`langc: can't read ${src}: ${(e as Error).message}`); process.exit(2); }

let c: string;
try { c = compileProgram(read(text)); }
catch (e) {
    if (e instanceof CompileError) { console.error(`${src}:${e.line}:${e.col}: ${e.message}`); process.exit(1); }
    console.error(`langc: internal error: ${(e as Error).stack}`); process.exit(2);
}

try { writeFileSync(`${out}.c`, c); }
catch (e) { console.error(`langc: can't write ${out}.c: ${(e as Error).message}`); process.exit(2); }

const cc = (process.env.LANG_CC ?? 'cc').split(' ');
const r = spawnSync(cc[0]!, [...cc.slice(1), '-O1', '-Wall', `-I${join(root, 'runtime')}`, '-o', out, `${out}.c`, join(root, 'runtime', 'rt.c')], { stdio: 'inherit' });
if (r.error) { console.error(`langc: can't run ${cc[0]}: ${r.error.message}`); process.exit(2); }
process.exit(r.status === 0 ? 0 : 2);
